// Passive Buzzer Melody Example
const int BUZZER_PIN = 8;

// Musical note frequencies in Hz
#define NOTE_C4 262
#define NOTE_E4 330
#define NOTE_G4 392
#define NOTE_C5 523

void setup() {
  // Play a celebratory 4-note ascending chord on boot
  int melody[] = { NOTE_C4, NOTE_E4, NOTE_G4, NOTE_C5 };
  int duration = 150; // milliseconds

  for (int i = 0; i < 4; i++) {
    tone(BUZZER_PIN, melody[i], duration);
    delay(duration * 1.30); // small pause between notes
  }
  noTone(BUZZER_PIN); // Stop sound
}

void loop() {
  // Silence during main loop
}
